package signplates.client;
import java.util.*;import net.fabricmc.fabric.api.client.model.loading.v1.ModelLoadingPlugin;import net.minecraft.client.resources.model.*;import net.minecraft.resources.ResourceLocation;
public final class PlateModels {public static void init(){ModelLoadingPlugin.register(context->{context.addModels(PlateBakedModel.componentIds());var caches=new PlateBakedModel.Caches();context.modifyModelAfterBake().register((model,ctx)->{var top=ctx.topLevelId();if(model==null||top==null||!top.id().getNamespace().equals("sign_plates")||!top.id().getPath().equals("sign_plate"))return model;var parts=new HashMap<ResourceLocation,BakedModel>();for(var id:PlateBakedModel.componentIds()){var part=ctx.baker().bake(id,BlockModelRotation.X0_Y0);if(part!=null)parts.put(id,part);}return new PlateBakedModel(model,Map.copyOf(parts),caches);});});}}
